package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The plans on a sheet, and the generate that makes their claims. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PlanClaimRepository made;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final Audit audit;

    public PlanService(PlanRepository plans, PlanClaimRepository made, PersonRepository people, ClaimService claims,
            SheetService sheets, Audit audit) {
        this.plans = plans;
        this.made = made;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's plans in the order they were added: as they stand now, or those added by the end
     *  of the as-of date. */
    public List<Plan> list(String sheetId, LocalDate asOf) {
        return plans.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(p -> asOf == null || !p.getMadeOn().isAfter(asOf))
                .toList();
    }

    /** How many claims each plan has made, by plan id: so far, or by the end of the as-of date. */
    public Map<Long, Integer> generated(List<Plan> them, LocalDate asOf) {
        Map<Long, Integer> counts = new HashMap<>();
        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
            if (asOf == null || !c.getMadeOn().isAfter(asOf)) {
                counts.merge(c.getPlanId(), 1, Integer::sum);
            }
        }
        return counts;
    }

    /** Add a plan for a person: an amount of 0.00 or more with up to two decimals, a start (blank: the
     *  sheet's today), either every so many days (a whole number, at least 1) or monthly on a day of the
     *  month (1 to 31), and an end on or after the start. */
    @Transactional
    public Plan add(String sheetId, String user, Long personId, String amount, LocalDate start, String every,
            String day, LocalDate end) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
        BigDecimal figure = amountOf(amount);
        boolean monthly = day != null && !day.isBlank();
        if (monthly && every != null && !every.isBlank()) {
            throw new PlanRefusedException("A plan runs either every so many days or on a day of the month");
        }
        Integer days = monthly ? null : everyOf(every);
        Integer dayOfMonth = monthly ? dayOf(day) : null;
        LocalDate today = sheets.today(sheetId);
        LocalDate from = start != null ? start : today;
        if (end == null || end.isBefore(from)) {
            throw new PlanRefusedException("A plan must end on or after its start");
        }
        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, figure, from, days, dayOfMonth, end, today));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + saved.getAmount().toPlainString() + " start=" + saved.getStart()
                + (monthly ? " day=" + saved.getDay() : " every=" + saved.getEvery()) + " end=" + saved.getEnd());
        return saved;
    }

    /** For every plan on the sheet, in the order they were added, add a DRAFT claim of its amount with
     *  an empty note for each plan date up to its end and the sheet's today it has made none for yet,
     *  as the claim form would; a date the form refuses is passed over, to be tried again next time.
     *  The claims made, in the order they were. */
    @Transactional
    public List<Claim> generate(String sheetId, String user) {
        sheets.lock(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Plan> them = plans.findBySheetIdOrderByIdAsc(sheetId);
        Set<String> done = new HashSet<>();
        for (PlanClaim c : made.findByPlanIdInOrderByIdAsc(them.stream().map(Plan::getId).toList())) {
            done.add(c.getPlanId() + "@" + c.getDate());
        }
        List<Claim> added = new ArrayList<>();
        for (Plan plan : them) {
            for (LocalDate date : plan.datesUpTo(today)) {
                if (done.contains(plan.getId() + "@" + date)
                        || !claims.accepts(sheetId, plan.getPersonId(), date)) {
                    continue;
                }
                Claim claim = claims.add(sheetId, user, plan.getPersonId(), plan.getAmount(), date, "", null);
                made.saveAndFlush(new PlanClaim(plan.getId(), date, claim.getId(), today));
                added.add(claim);
            }
        }
        return added;
    }

    private static BigDecimal amountOf(String amount) {
        BigDecimal figure;
        try {
            figure = new BigDecimal(amount == null ? "" : amount.trim());
        } catch (NumberFormatException e) {
            throw new PlanRefusedException("The amount is not a number");
        }
        if (figure.signum() < 0 || figure.scale() > 2 || figure.precision() - figure.scale() > 10) {
            throw new PlanRefusedException("The amount must be 0.00 or more, with up to two decimals");
        }
        return figure.setScale(2);
    }

    private static int everyOf(String every) {
        String typed = every == null ? "" : every.trim();
        if (!typed.matches("\\d{1,6}") || Integer.parseInt(typed) < 1) {
            throw new PlanRefusedException("A plan runs every whole number of days, at least 1");
        }
        return Integer.parseInt(typed);
    }

    private static int dayOf(String day) {
        String typed = day.trim();
        if (!typed.matches("\\d{1,2}") || Integer.parseInt(typed) < 1 || Integer.parseInt(typed) > 31) {
            throw new PlanRefusedException("A monthly plan runs on a day of the month, 1 to 31");
        }
        return Integer.parseInt(typed);
    }
}
package net.officefloor.hq.app.plan;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/plans")
public class PlanController {

    /** A plan as the screen shows it, with how many claims it has made so far. */
    public record PlanView(Long id, Long personId, String amount, LocalDate start, Integer every,
            Integer day, LocalDate end, int generated) {
        static PlanView of(Plan plan, int generated) {
            return new PlanView(plan.getId(), plan.getPersonId(), plan.getAmount().toPlainString(), plan.getStart(),
                    plan.getEvery(), plan.getDay(), plan.getEnd(), generated);
        }
    }

    /** A plan's fields as typed: the amount, interval and day of the month are checked by the service;
     *  a blank start takes the sheet's today. */
    public record PlanRequest(@NotNull Long personId, @Size(max = 50) String amount, LocalDate start,
            @Size(max = 50) String every, @Size(max = 50) String day, LocalDate end) {
    }

    /** The claims a generate made, in the order it made them, and the sheet's plans after it. */
    public record GenerateView(List<ClaimView> made, List<PlanView> plans) {
    }

    private final PlanService service;
    private final ClaimService claims;
    private final RollupService rollups;

    public PlanController(PlanService service, ClaimService claims, RollupService rollups) {
        this.service = service;
        this.claims = claims;
        this.rollups = rollups;
    }

    /** The sheet's plans in the order they were added: as they stand now, or as they stood at the end
     *  of the screen's as-of date. */
    @GetMapping
    public List<PlanView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        return views(sheetId.trim(), AsOf.parse(asOfHeader));
    }

    /** Add a plan for a person on the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PlanView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PlanRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return PlanView.of(service.add(sheet, by, request.personId(), request.amount(), request.start(),
                request.every(), request.day(), request.end()), 0);
    }

    /** Make the plans' claims due by the sheet's today, then record the figures they moved. */
    @PostMapping("/generate")
    public GenerateView generate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        List<Claim> made = rollups.track(sheet, by, () -> service.generate(sheet, by));
        return new GenerateView(made.stream()
                .map(c -> ClaimView.of(c, claims.roundsBy(sheet, c), claims.logOf(c.getId()), List.of()))
                .toList(), views(sheet, null));
    }

    private List<PlanView> views(String sheet, LocalDate asOf) {
        List<Plan> them = service.list(sheet, asOf);
        Map<Long, Integer> generated = service.generated(them, asOf);
        return them.stream().map(p -> PlanView.of(p, generated.getOrDefault(p.getId(), 0))).toList();
    }

    /** A bad amount, interval or day of the month, an end before the start, or a date that is not a real yyyy-mm-dd date. */
    @ExceptionHandler({PlanRefusedException.class, HttpMessageNotReadableException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void refused() {
    }

    /** A claim the form would refuse after all. */
    @ExceptionHandler({PeriodClosedException.class, PersonRetiredException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void conflict() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: a DRAFT claim of its amount (two decimals) for every plan date up to its end. The
 *  plan dates are its start and then every so many days, or, for a monthly plan, its day of the month
 *  in every month from the start's month (a day beyond the month's length on its last day), those
 *  before the start left out. */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    /** Every so many days; null for a monthly plan. */
    @Column(name = "every_days")
    private Integer every;

    /** The day of the month (1 to 31) a monthly plan runs on; null for one that runs every so many days. */
    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    /** The sheet's today when the plan was added. */
    @Column(name = "made_on", nullable = false, updatable = false)
    private LocalDate madeOn;

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end, LocalDate madeOn) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
        this.madeOn = madeOn;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    public LocalDate getMadeOn() {
        return madeOn;
    }

    /** The plan's dates up to its end and the day given, the earliest first. */
    public List<LocalDate> datesUpTo(LocalDate upTo) {
        LocalDate last = end.isBefore(upTo) ? end : upTo;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            dates.add(d);
        }
        return dates;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, Injectable, computed, effect, inject, input, output, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { AMOUNT, Claim } from '../claims/claims';

export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  /** Every so many days after the start, a plan date; null for a monthly plan. */
  every: number | null;
  /** The day of the month (1 to 31) a monthly plan runs on; null for one that runs every so many days. */
  day: number | null;
  end: string;
  /** How many claims the plan has made so far. */
  generated: number;
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const EVERY = /^\d{1,6}$/;
const DAY = /^\d{1,2}$/;

// The active sheet's plans in the order they were added, re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class PlanStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly plans = signal<Plan[]>([]);

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.plans.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }

  /** Add a plan for a person; the server refuses a bad amount, interval or day of the month, or an end
   *  before the start. */
  async add(
    personId: number,
    fields: { amount: string; start: string | null; every: string | null; day: string | null; end: string },
  ): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.post<Plan>(`/api/sheets/${encodeURIComponent(sheet)}/plans`, { personId, ...fields }),
    );
    if (this.session.sheetId() !== sheet) return;
    this.plans.update((list) => [...list.filter((p) => p.id !== saved.id), saved]);
  }

  /** Make every plan's claims due by the sheet's today; gives back the claims made. */
  async generate(): Promise<Claim[]> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const result = await firstValueFrom(
      this.http.post<{ made: Claim[]; plans: Plan[] }>(`/api/sheets/${encodeURIComponent(sheet)}/plans/generate`, {}),
    );
    if (this.session.sheetId() !== sheet) return [];
    this.plans.set(result.plans);
    return result.made;
  }

  private async read(sheet: string, load: number): Promise<void> {
    const list = await firstValueFrom(this.http.get<Plan[]>(`/api/sheets/${encodeURIComponent(sheet)}/plans`));
    if (this.session.loads() !== load) return;
    this.plans.set(list);
  }
}

// A person's plans, each with how many claims it has made, and the form that adds one.
@Component({
  selector: 'app-person-plans',
  template: `
    <ul [attr.aria-label]="'Plans of ' + name()">
      @for (pl of plans(); track pl.id) {
        <li [attr.data-testid]="'plan-row-' + pl.id">
          <span data-testid="plan-amount-shown">{{ pl.amount }}</span>
          from <span data-testid="plan-start">{{ pl.start }}</span>
          @if (pl.day !== null) {
            monthly on day <span data-testid="plan-day">{{ pl.day }}</span>
          } @else {
            every <span data-testid="plan-every">{{ pl.every }}</span> days
          }
          to <span data-testid="plan-end">{{ pl.end }}</span>;
          made <span data-testid="plan-generated">{{ pl.generated }}</span>
        </li>
      }
    </ul>
    <form (submit)="submit($event)" [attr.aria-label]="'Add a plan for ' + name()">
      <label [for]="'plan-form-amount-' + personId()">Plan amount</label>
      <input
        [id]="'plan-form-amount-' + personId()"
        data-testid="plan-form-amount"
        inputmode="decimal"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-start-' + personId()">Start</label>
      <input
        type="date"
        [id]="'plan-form-start-' + personId()"
        data-testid="plan-form-start"
        [value]="start()"
        (input)="start.set(value($event)); error.set(null)"
      />
      <label [for]="'plan-form-every-' + personId()">Every (days)</label>
      <input
        [id]="'plan-form-every-' + personId()"
        data-testid="plan-form-every"
